//! Layouts generated by a test.

use text_mesh_core::Alignment;
use text_mesh_layout::{Element, Layout, Line};

/// Line ascender, descender, and baseline as y offsets from the layout's top.
#[derive(Clone, Copy)]
pub struct LineMetrics {
    pub ascender: f32,
    pub descender: f32,
    pub baseline: f32,
}

/// Places `elements` on one left-aligned line of height 20 in a 200-by-`height` box using `metrics`.
#[must_use]
pub fn single_line(elements: Vec<Element>, height: f32, metrics: LineMetrics) -> Layout {
    let LineMetrics {
        ascender,
        descender,
        baseline,
    } = metrics;

    Layout {
        width: 200.0,
        height,
        preferred_height: height,
        lines: vec![Line {
            first: 0,
            last: elements.len().saturating_sub(1),
            ascender,
            descender,
            baseline,
            line_height: 20.0,
            width: 200.0,
            length: 0.0,
            margin_left: 0.0,
            margin_right: 0.0,
            alignment: Alignment::Left,
        }],
        elements,
    }
}
